$("#subject_id").change(function() {
    let subject = $("#subject_id").val(); 
    let class_id = $("#class_id").val(); 

    if (subject || class_id) { 
        const subject_name = $(this).find(':selected').text();
        loadData(subject_name, class_id);
    } else {
        console.log("Subject or Class  is not found");
    }
});



function loadData(subject_name ,class_id) {
    $("#reslte_subject_r tbody").html('');

    let sendingData = {
        "class_id": class_id,
        "subject_name": subject_name ,
        "action" : "subject_read_r"
    };

    $.ajax({
        method: "POST",
        dataType: "JSON",
        url: "../APi/cre_result.php",
        data: sendingData,
        success: function(data) {
            let status = data.status;
            let response = data.data;
            let tr = '';

            if (status) {
            
                 
                response.forEach(itm => {
                    tr += "<tr>";
                    for (let i in itm) {
                        tr += `<td>${itm[i]}</td>`;
                    }
                    tr += `<td>
                                <button class="btn_upda"> 
                                    <a class="updete_cl" update_id="${itm['result_id']}">
                                        <span class="material-symbols-outlined" style="color:#fff;background-color:var(--base-clr); font-size: xx-large; font-weight: bold; border-radius: 5px;">
                                            edit
                                        </span>
                                    </a>
                                </button> 
                                &nbsp;&nbsp;
                                <a class="delete_cl" delete_id="${itm['result_id']}">
                                    <span class="material-symbols-outlined" style="color:#fff;background-color:red;font-size: xx-large; font-weight: bold; border-radius: 5px;">
                                        delete
                                    </span>
                                </a>
                            </td>`;
                    tr += '</tr>';
                });

                $("#reslte_subject_r tbody").append(tr);
            } else {
                console.log("error", response);
            }
        },
        error: function(data) {
            console.log(data);
        }
    });
}

